"""Lay students out in rows of seats."""

from typing import List

from rosterkit.models import Student


def _row_line(index: int, chunk: List[Student]) -> str:
    names = " | ".join(item.display_name for item in chunk)
    return f"Row {index}: {names}"


def _lines(ordered: List[Student], seats: int) -> List[str]:
    starts = range(0, len(ordered), seats)
    return [
        _row_line(index, ordered[begin:begin + seats])
        for index, begin in enumerate(starts, 1)
    ]


def _by_name(people: List[Student]) -> List[Student]:
    key = lambda item: (item.last_name, item.first_name)
    return sorted(people, key=key)


# ---
def seat_rows(people: List[Student], seats: int):
    if seats < 1 or not people:
        raise ValueError("need students and a seat count")
    return _lines(_by_name(people), seats)

