# owner: platform
import unittest

from rosterkit.seating import seat_rows
from rosterkit.models import Student


def _student(last, first):
    return Student("id", last, first, "A")


class SeatRowsTests(unittest.TestCase):
    def test_sorted_and_chunked(self):
        people = [
            _student("Halloway", "Juno"),
            _student("Zeller", "Ann"),
            _student("Dunmere", "Piet"),
        ]
        self.assertEqual(
            seat_rows(people, 2),
            [
                "Row 1: Dunmere, Piet | Halloway, Juno",
                "Row 2: Zeller, Ann",
            ],
        )

    def test_bad_seat_count(self):
        people = [_student("Dunmere", "Piet")]
        for seats in (0, -1):
            with self.assertRaises(ValueError):
                seat_rows(people, seats)

    def test_no_students(self):
        with self.assertRaises(ValueError):
            seat_rows([], 3)
